<?php $this->layout('layouts/studio'); ?>
<?php $status = $page->status ?? 'draft'; $statusLabel = ['post' => 'Publicada', 'draft' => 'Rascunho', 'trash' => 'Lixeira'][$status] ?? 'Rascunho'; ?>
<section class="studio-page-header studio-editor-heading"><div><small>CONTEÚDO</small><h2><?= $page ? 'Editar página' : 'Nova página' ?></h2><p>Configure o conteúdo e a publicação desta página.</p></div><div class="actions"><a class="studio-btn" href="<?= url('/studio/pages') ?>">Voltar</a></div></section>
<form class="studio-form studio-post-editor" action="<?= url('/studio/page' . ($page ? '/' . $page->id : '')) ?>" method="post" enctype="multipart/form-data">
    <?= csrf_input() ?><input type="hidden" name="action" value="<?= $page ? 'update' : 'create' ?>">
    <div class="studio-post-layout">
        <section class="studio-panel studio-post-content">
            <label>Título da página *<input id="page-title" name="title" maxlength="140" value="<?= htmlspecialchars($page->title ?? '') ?>" placeholder="Um título claro para a página" required><small><span data-title-count>0</span>/140 caracteres</small></label>
            <label>Endereço amigável<input id="page-uri" name="uri" maxlength="180" value="<?= htmlspecialchars($page->uri ?? '') ?>" placeholder="gerado-automaticamente-pelo-titulo"><small>Gerado pelo título. Use só letras, números e hífen.</small></label>
            <label>Conteúdo *<textarea data-moves-editor="full" data-editor-height="620" id="page-content" name="content" rows="22" required><?= htmlspecialchars((string)($page->content ?? ''), ENT_QUOTES) ?></textarea></label>
            <button class="studio-btn" type="button" data-media-picker data-media-editor="page-content"><ion-icon name="images-outline"></ion-icon>Inserir imagem da biblioteca</button>
        </section>
        <aside class="studio-post-sidebar">
            <section class="studio-panel"><header><div><small>PUBLICAÇÃO</small><h2>Status e data</h2></div><span class="status <?= htmlspecialchars($status) ?>"><?= $statusLabel ?></span></header><input type="hidden" name="status" value="<?= htmlspecialchars($status) ?>"><label>Publicar em<input type="datetime-local" name="post_at" value="<?= date('Y-m-d\TH:i', strtotime($page->post_at ?? 'now')) ?>" required></label><div class="studio-publish-actions"><button class="studio-btn" type="submit" name="submit_status" value="draft" onclick="this.form.elements.status.value='draft'">Salvar rascunho</button><button class="studio-btn primary" type="submit" name="submit_status" value="post" onclick="this.form.elements.status.value='post'"><?= $page && $status === 'post' ? 'Atualizar' : 'Publicar' ?></button></div></section>
            <section class="studio-panel"><header><div><small>DESTAQUE</small><h2>Imagem de capa</h2></div></header><input type="hidden" id="page-library-cover" name="library_cover"><input id="page-cover" type="file" data-max-mb="10" aria-label="Imagem de capa" data-cx-upload-label="Arraste a imagem de capa aqui ou" name="cover" accept="image/jpeg,image/png,image/webp"><button class="studio-btn studio-media-pick" type="button" data-media-picker data-media-target="#page-library-cover" data-media-preview=".page-cover-preview"><ion-icon name="images-outline"></ion-icon>Escolher da biblioteca</button><img class="studio-preview studio-post-cover-preview page-cover-preview <?= empty($page->cover) ? 'is-empty' : '' ?>" src="<?= !empty($page->cover) ? image($page->cover, 600) : '' ?>" alt="Prévia da capa"></section>
            <?php if ($page): ?><section class="studio-panel studio-danger-zone"><header><div><small>CUIDADO</small><h2>Excluir página</h2></div></header><p>Esta ação remove a página do site.</p><button class="studio-btn danger" type="submit" name="action" value="delete" data-cn-confirm="Excluir esta página? Ela sai do site e o endereço dela deixa de abrir." data-confirm-undo="nao" data-confirm-action="Excluir página">Excluir página</button><input type="hidden" name="page_id" value="<?= $page->id ?>"></section><?php endif; ?>
        </aside>
    </div>
</form>
<?php $this->start('scripts') ?><script>
(()=>{const title=document.querySelector('#page-title'),uri=document.querySelector('#page-uri'),cover=document.querySelector('#page-cover'),preview=document.querySelector('.page-cover-preview');const slug=v=>v.normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(uri.value)uri.dataset.changed='1';const update=()=>{document.querySelector('[data-title-count]').textContent=title.value.length;if(!uri.dataset.changed)uri.value=slug(title.value)};title?.addEventListener('input',update);uri?.addEventListener('input',()=>{uri.dataset.changed='1';uri.value=slug(uri.value)});cover?.addEventListener('change',()=>{const file=cover.files?.[0];if(file){preview.src=URL.createObjectURL(file);preview.classList.remove('is-empty')}});update();})();
</script><?php $this->stop() ?>
